fn peval(p:&P,v:[u64;4])->u64{p.iter().fold(0,|s,(e,&a)|add(s,mul(a,(0..4).fold(1,|b,j|mul(b,pow(v[j],e[j]as u64))))))}
fn substitute(p:&P,vars:&[P;4])->P{let mut out=P::new();for(e,&a)in p{let mut v=P::from([([0;4],a)]);for j in 0..4{for _ in 0..e[j]{v=product(&v,&vars[j]);}}for(e,a)in v{term(&mut out,e,a);}}out.retain(|_,a|*a!=0);out}
fn node_transform(p:&P,node:[u64;4])->P{assert_eq!(node[0],1);let vars=[P::from([([0,0,0,1],1)]),P::from([([1,0,0,0],1),([0,0,0,1],node[1])]),P::from([([0,1,0,0],1),([0,0,0,1],node[2])]),P::from([([0,0,1,0],1),([0,0,0,1],node[3])])];substitute(p,&vars)}
fn bilinear(a:&P,p:[u64;4],d:[u64;4])->u64{let sum=std::array::from_fn(|j|add(p[j],d[j]));sub(sub(peval(a,sum),peval(a,p)),peval(a,d))}
fn branch_poly(f:&P)->Vec<u64>{assert!(f.keys().all(|e|e[3]<=2));let a:P=f.iter().filter(|(e,_)|e[3]==2).map(|(e,&v)|{let mut e=*e;e[3]=0;(e,v)}).collect();let b:P=f.iter().filter(|(e,_)|e[3]==1).map(|(e,&v)|{let mut e=*e;e[3]=0;(e,v)}).collect();
 let gram:Vec<Vec<u64>>=(0..3).map(|i|(0..3).map(|j|{let mut x=[0;4];x[i]=1;let mut y=[0;4];y[j]=1;mul(bilinear(&a,x,y),pow(2,Q-2))}).collect()).collect();assert_eq!(rref(gram).0.len(),3);
 let mut branch=vec![];for x in 0..Q{for y in 0..Q{let v=[1,x,y,0];if peval(&a,v)==0&&peval(&b,v)==0{branch.push(v)}}}for x in 0..Q{let v=[0,1,x,0];if peval(&a,v)==0&&peval(&b,v)==0{branch.push(v)}}if peval(&a,[0,0,1,0])==0&&peval(&b,[0,0,1,0])==0{branch.push([0,0,1,0])}assert_eq!(branch.len(),1);let p=branch[0];let pivot=(0..3).find(|&j|p[j]!=0).unwrap();let axes:Vec<_>=(0..3).filter(|&j|j!=pivot).collect();let mut d0=[0;4];d0[axes[0]]=1;let mut d1=[0;4];d1[axes[1]]=1;let l0=bilinear(&a,p,d0);let l1=bilinear(&a,p,d1);assert!(l0!=0||l1!=0);let mut u=[0;4];u[axes[0]]=l1;u[axes[1]]=sub(0,l0);let v=if l0!=0{d0}else{d1};
 let directions:[P;4]=std::array::from_fn(|j|{let mut q=P::new();term(&mut q,[1,0,0,0],u[j]);term(&mut q,[0,1,0,0],v[j]);q});let ad=substitute(&a,&directions);let lu=bilinear(&a,p,u);assert_eq!(lu,0);let lv=bilinear(&a,p,v);let lp=P::from([([0,1,0,0],lv)]);let param:[P;4]=std::array::from_fn(|j|{let mut q=P::new();for(e,&x)in &ad{term(&mut q,*e,mul(p[j],x))}for(e,x)in product(&lp,&directions[j]){term(&mut q,e,sub(0,x));}q});assert!(substitute(&a,&param).is_empty());let sextic=substitute(&b,&param);assert_eq!(*sextic.get(&[6,0,0,0]).unwrap_or(&0),0);let mut cs=vec![0;6];for(e,v)in sextic{assert_eq!(e[0]+e[1],6);assert_eq!(e[2]+e[3],0);if e[0]<6{cs[e[0]as usize]=v;}}assert_ne!(cs[5],0);let poly=Poly::from_coeffs(&cs);assert_eq!(Poly::gcd(&poly,&poly.deriv(&Fp::new(Q)),&Fp::new(Q)).deg(),0);println!("BRANCH\tpoint={p:?}\ttangent_direction={u:?}\tcomplement={v:?}\tcoefficients={cs:?}");cs}
fn eval1(cs:&[u64],x:u64)->u64{cs.iter().rev().fold(0,|s,&a|add(mul(s,x),a))}
fn counts(cs:&[u64])->(i64,i64){let fp=Fp::new(Q);let n1=Q as i64+1+(0..Q).map(|x|fp.legendre(eval1(cs,x))as i64).sum::<i64>();let mut total=0i64;for x in 0..Q{for y in 0..Q{let(mut a,mut b)=(0,0);for &c in cs.iter().rev(){let na=add(add(mul(a,x),mul(7,mul(b,y))),c);let nb=add(mul(a,y),mul(b,x));a=na;b=nb;}let norm=sub(mul(a,a),mul(7,mul(b,b)));total+=fp.legendre(norm)as i64;}}(n1,(Q*Q+1)as i64+total)}
fn main(){counted::disable();let source=P::from([([0,0,4,0],1),([0,2,0,2],1),([0,1,2,1],Q-2),([1,0,1,2],Q-4),([3,0,0,1],Q-28),([1,3,0,0],Q-28),([2,1,1,0],28)]);let coeff:Vec<u64>=include_str!("../image-quartic/CONTROL.txt").lines().find(|l|l.starts_with("TARGET_QUARTIC\t")).unwrap().split('\t').nth(1).unwrap().split(',').map(|s|s.parse().unwrap()).collect();let target: P=monomials(4).into_iter().zip(coeff).filter(|(_,v)|*v!=0).collect();let target=node_transform(&target,[1,284,243,459]);
 for(name,p)in[("source_control",source),("quotient_candidate",target)]{println!("MODEL\t{name}");let mut cs=branch_poly(&p);let(n1,n2)=counts(&cs);assert!([523,681].contains(&n1));assert_eq!(n2,360423);let scale=if n1==681{1}else{7};for x in &mut cs{*x=mul(*x,scale)}let(final1,final2)=counts(&cs);assert_eq!((final1,final2),(681,360423));let a1=final1-Q as i64-1;let s2=(Q*Q+1)as i64-final2;assert_eq!((a1*a1-s2)%2,0);let a2=(a1*a1-s2)/2;let order=1+a1+a2+Q as i64*a1+(Q*Q)as i64;assert_eq!(order,411491);println!("RECOVERED\t{name}\tcoefficients={cs:?}\ttwist_scale={scale}\tpoints_q={final1}\tpoints_q2={final2}\ta1={a1}\ta2={a2}\tjacobian_order={order}");}
 println!("node_conic_nondegenerate=true branch_squarefree_degree5=true both_twists_resolved_by_two_field_counts=true independent_verification=false");}
